 "content": "def transform(g):
    h,w=len(g),len(g[0]); bg=g[0][0]
    # 3x3 seed pattern is at the upper-left; background-colored cells in it
    # are transparent. Each isolated zero is the anchor for a copy of the seed.
    pattern=[row[:3] for row in g[:3]]
    out=[[bg]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0:
                for i in range(3):
                    for j in range(3):
                        v=pattern[i][j]
                        rr=r+i-1; cc=c+j-1
                        if v!=bg and 0<=rr<h and 0<=cc<w:
                            out[rr][cc]=v
    return out
"
}

